INSERT INTO word_items (id, set_name, set_slug, en, vi, part, topic, note, other_answers, example_en, example_vi, sort_order, created_at, updated_at) VALUES
('wc-s1-01', 'Starter 1', 'starter-1', 'quit a job', 'từ bỏ một công việc', 'Vocab', 'Collocation', NULL, NULL, 'Sam wants to quit a job because it is boring.', 'Sam muốn từ bỏ một công việc vì nó nhàm chán.', 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-02', 'Starter 1', 'starter-1', 'solve a problem', 'giải quyết một vấn đề', 'Vocab', 'Collocation', NULL, NULL, 'We can solve a problem together.', 'Chúng ta có thể cùng nhau giải quyết một vấn đề.', 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-03', 'Starter 1', 'starter-1', 'participate in an event', 'tham gia vào một sự kiện', 'Vocab', 'Collocation', 'Giới từ: participate + IN', NULL, 'I want to participate in an event next week.', 'Tôi muốn tham gia vào một sự kiện vào tuần sau.', 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-04', 'Starter 1', 'starter-1', 'make an appointment', 'đặt một cuộc hẹn', 'Vocab', 'Collocation', NULL, NULL, 'Please make an appointment with the doctor.', 'Vui lòng đặt một cuộc hẹn với bác sĩ.', 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-05', 'Starter 1', 'starter-1', 'return from a business trip', 'trở về từ một chuyến công tác', 'Vocab', 'Collocation', 'Giới từ: return + FROM', NULL, 'Mr. Lee will return from a business trip on Friday.', 'Ông Lee sẽ trở về từ một chuyến công tác vào thứ Sáu.', 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-06', 'Starter 1', 'starter-1', 'fill out a form', 'điền vào một biểu mẫu', 'Vocab', 'Collocation', 'fill out và fill in đều đúng', 'fill in a form', 'Please fill out a form at the front desk.', 'Vui lòng điền vào một biểu mẫu tại quầy lễ tân.', 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-07', 'Starter 1', 'starter-1', 'pay for a taxi', 'trả tiền cho một chuyến taxi', 'Vocab', 'Collocation', 'Giới từ: pay + FOR', NULL, 'I must pay for a taxi to the airport.', 'Tôi phải trả tiền cho một chuyến taxi ra sân bay.', 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-08', 'Starter 1', 'starter-1', 'apply for a job', 'nộp đơn xin một công việc', 'Vocab', 'Collocation', 'Giới từ: apply + FOR', NULL, 'She wants to apply for a job at a bank.', 'Cô ấy muốn nộp đơn xin một công việc tại một ngân hàng.', 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-09', 'Starter 1', 'starter-1', 'transfer some money', 'chuyển một ít tiền', 'Vocab', 'Collocation', NULL, NULL, 'I want to transfer some money to my mother.', 'Tôi muốn chuyển một ít tiền cho mẹ.', 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-10', 'Starter 1', 'starter-1', 'contact the office', 'liên hệ với văn phòng', 'Vocab', 'Collocation', 'contact + tân ngữ, không thêm ''with''', NULL, 'Please contact the office if you have a question.', 'Vui lòng liên hệ với văn phòng nếu bạn có câu hỏi.', 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-11', 'Starter 1', 'starter-1', 'promote sales', 'thúc đẩy doanh số', 'Vocab', 'Collocation', NULL, NULL, 'The new ad can promote sales.', 'Quảng cáo mới có thể thúc đẩy doanh số.', 11, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-12', 'Starter 1', 'starter-1', 'announce something', 'thông báo một điều gì đó', 'Vocab', 'Collocation', NULL, NULL, 'The manager wants to announce something today.', 'Người quản lý muốn thông báo một điều gì đó hôm nay.', 12, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-13', 'Starter 1', 'starter-1', 'repair a car', 'sửa chữa một chiếc xe hơi', 'Vocab', 'Collocation', NULL, NULL, 'The shop can repair a car in two days.', 'Cửa hàng có thể sửa chữa một chiếc xe hơi trong hai ngày.', 13, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-14', 'Starter 1', 'starter-1', 'complete a project', 'hoàn thành một dự án', 'Vocab', 'Collocation', NULL, NULL, 'Our team will complete a project by May.', 'Nhóm của chúng tôi sẽ hoàn thành một dự án trước tháng Năm.', 14, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-15', 'Starter 1', 'starter-1', 'do business', 'làm kinh doanh', 'Vocab', 'Collocation', NULL, NULL, 'Many people do business online today.', 'Ngày nay nhiều người làm kinh doanh trực tuyến.', 15, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s1-16', 'Starter 1', 'starter-1', 'highly recommend', 'rất khuyên dùng', 'Vocab', 'Collocation', NULL, NULL, 'I highly recommend this hotel.', 'Tôi rất khuyên dùng khách sạn này.', 16, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT INTO word_items (id, set_name, set_slug, en, vi, part, topic, note, other_answers, example_en, example_vi, sort_order, created_at, updated_at) VALUES
('wc-s2-01', 'Starter 2', 'starter-2', 'account information', 'thông tin tài khoản', 'Vocab', 'Nouns', NULL, NULL, 'Please check your account information before you log in.', 'Vui lòng kiểm tra thông tin tài khoản của bạn trước khi đăng nhập.', 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-02', 'Starter 2', 'starter-2', 'customer satisfaction', 'sự hài lòng của khách hàng', 'Vocab', 'Nouns', NULL, NULL, 'The company wants to improve customer satisfaction this year.', 'Công ty muốn cải thiện sự hài lòng của khách hàng trong năm nay.', 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-03', 'Starter 2', 'starter-2', 'a reliable technician', 'một kỹ thuật viên đáng tin cậy', 'Vocab', 'Nouns', NULL, NULL, 'We need a reliable technician to fix the machine.', 'Chúng ta cần một kỹ thuật viên đáng tin cậy để sửa máy.', 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-04', 'Starter 2', 'starter-2', 'safety measures', 'các biện pháp an toàn', 'Vocab', 'Nouns', NULL, NULL, 'The factory has new safety measures for all workers.', 'Nhà máy có các biện pháp an toàn mới cho mọi công nhân.', 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-05', 'Starter 2', 'starter-2', 'a production schedule', 'một lịch sản xuất', 'Vocab', 'Nouns', NULL, NULL, 'The factory follows a production schedule every week.', 'Nhà máy tuân theo một lịch sản xuất mỗi tuần.', 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-06', 'Starter 2', 'starter-2', 'interest rates', 'lãi suất', 'Vocab', 'Nouns', NULL, NULL, 'The bank changed its interest rates last month.', 'Ngân hàng đã thay đổi lãi suất vào tháng trước.', 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-07', 'Starter 2', 'starter-2', 'a computer analysis', 'một phân tích bằng máy tính', 'Vocab', 'Nouns', NULL, NULL, 'The team ran a computer analysis of the sales data.', 'Nhóm đã thực hiện một phân tích bằng máy tính về dữ liệu bán hàng.', 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-08', 'Starter 2', 'starter-2', 'a keynote speaker', 'một diễn giả chính', 'Vocab', 'Nouns', NULL, NULL, 'Dr. Tran was a keynote speaker at the conference.', 'Ông Trần là một diễn giả chính tại hội nghị.', 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-09', 'Starter 2', 'starter-2', 'make an appointment', 'đặt một cuộc hẹn', 'Vocab', 'Nouns', NULL, NULL, 'I need to make an appointment with the dentist.', 'Tôi cần đặt một cuộc hẹn với nha sĩ.', 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-10', 'Starter 2', 'starter-2', 'close for renovations', 'đóng cửa để sửa chữa', 'Vocab', 'Nouns', NULL, NULL, 'The restaurant will close for renovations next week.', 'Nhà hàng sẽ đóng cửa để sửa chữa vào tuần sau.', 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-11', 'Starter 2', 'starter-2', 'sign a contract', 'ký một hợp đồng', 'Vocab', 'Nouns', NULL, NULL, 'Both companies will sign a contract on Monday.', 'Cả hai công ty sẽ ký một hợp đồng vào thứ Hai.', 11, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-12', 'Starter 2', 'starter-2', 'establish an organization', 'thành lập một tổ chức', 'Vocab', 'Nouns', NULL, NULL, 'They plan to establish an organization to help students.', 'Họ dự định thành lập một tổ chức để giúp học sinh.', 12, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-13', 'Starter 2', 'starter-2', 'at your convenience', 'vào lúc thuận tiện cho bạn', 'Vocab', 'Nouns', NULL, NULL, 'Please call me back at your convenience.', 'Vui lòng gọi lại cho tôi vào lúc thuận tiện cho bạn.', 13, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-14', 'Starter 2', 'starter-2', 'public transportation', 'giao thông công cộng', 'Vocab', 'Nouns', NULL, NULL, 'Many people in the city use public transportation.', 'Nhiều người trong thành phố sử dụng giao thông công cộng.', 14, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-15', 'Starter 2', 'starter-2', 'reach an agreement', 'đạt được một thỏa thuận', 'Vocab', 'Nouns', NULL, NULL, 'The two managers need to reach an agreement.', 'Hai người quản lý cần đạt được một thỏa thuận.', 15, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s2-16', 'Starter 2', 'starter-2', 'work as a consultant', 'làm việc như một nhà tư vấn', 'Vocab', 'Nouns', NULL, NULL, 'She wants to work as a consultant.', 'Cô ấy muốn làm việc như một nhà tư vấn.', 16, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT INTO word_items (id, set_name, set_slug, en, vi, part, topic, note, other_answers, example_en, example_vi, sort_order, created_at, updated_at) VALUES
('wc-s3-01', 'Starter 3', 'starter-3', 'various attempts', 'nhiều lần cố gắng khác nhau', 'Vocab', 'Adjectives', NULL, NULL, 'He made various attempts to fix the printer.', 'Anh ấy đã có nhiều lần cố gắng khác nhau để sửa máy in.', 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-02', 'Starter 3', 'starter-3', 'a prominent businessman', 'một doanh nhân nổi tiếng', 'Vocab', 'Adjectives', NULL, NULL, 'Mr. Kim is a prominent businessman in this city.', 'Ông Kim là một doanh nhân nổi tiếng trong thành phố này.', 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-03', 'Starter 3', 'starter-3', 'proper actions', 'những hành động đúng đắn', 'Vocab', 'Adjectives', NULL, NULL, 'The manager took proper actions to solve the problem.', 'Người quản lý đã thực hiện những hành động đúng đắn để giải quyết vấn đề.', 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-04', 'Starter 3', 'starter-3', 'a permanent staff', 'đội ngũ nhân viên chính thức', 'Vocab', 'Adjectives', NULL, NULL, 'The company hired a permanent staff for the new office.', 'Công ty đã tuyển đội ngũ nhân viên chính thức cho văn phòng mới.', 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-05', 'Starter 3', 'starter-3', 'a significant difference', 'một sự khác biệt đáng kể', 'Vocab', 'Adjectives', NULL, NULL, 'There is a significant difference between the two prices.', 'Có một sự khác biệt đáng kể giữa hai mức giá.', 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-06', 'Starter 3', 'starter-3', 'the entire plan', 'toàn bộ kế hoạch', 'Vocab', 'Adjectives', NULL, NULL, 'We need to review the entire plan before Friday.', 'Chúng ta cần xem lại toàn bộ kế hoạch trước thứ Sáu.', 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-07', 'Starter 3', 'starter-3', 'an essential factor', 'một yếu tố thiết yếu', 'Vocab', 'Adjectives', NULL, NULL, 'Good communication is an essential factor for teamwork.', 'Giao tiếp tốt là một yếu tố thiết yếu cho làm việc nhóm.', 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-08', 'Starter 3', 'starter-3', 'an innovative job', 'một công việc mang tính sáng tạo', 'Vocab', 'Adjectives', NULL, NULL, 'She found an innovative job at a technology company.', 'Cô ấy đã tìm được một công việc mang tính sáng tạo tại một công ty công nghệ.', 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-09', 'Starter 3', 'starter-3', 'an impressive speech', 'một bài phát biểu gây ấn tượng', 'Vocab', 'Adjectives', NULL, NULL, 'The CEO gave an impressive speech at the meeting.', 'Giám đốc điều hành đã có một bài phát biểu gây ấn tượng tại cuộc họp.', 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-10', 'Starter 3', 'starter-3', 'a productive suggestion', 'một đề xuất mang lại hiệu quả', 'Vocab', 'Adjectives', NULL, NULL, 'My colleague gave a productive suggestion for the project.', 'Đồng nghiệp của tôi đã đưa ra một đề xuất mang lại hiệu quả cho dự án.', 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-11', 'Starter 3', 'starter-3', 'legal conditions', 'các điều kiện pháp lý', 'Vocab', 'Adjectives', NULL, NULL, 'The contract lists all the legal conditions clearly.', 'Hợp đồng liệt kê rõ tất cả các điều kiện pháp lý.', 11, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-12', 'Starter 3', 'starter-3', 'a competitive market', 'một thị trường cạnh tranh', 'Vocab', 'Adjectives', NULL, NULL, 'Selling phones is hard in a competitive market.', 'Bán điện thoại rất khó trong một thị trường cạnh tranh.', 12, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-13', 'Starter 3', 'starter-3', 'formal clothes', 'trang phục lịch sự', 'Vocab', 'Adjectives', NULL, NULL, 'Employees must wear formal clothes at the office.', 'Nhân viên phải mặc trang phục lịch sự tại văn phòng.', 13, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-14', 'Starter 3', 'starter-3', 'an official report', 'một báo cáo chính thức', 'Vocab', 'Adjectives', NULL, NULL, 'The manager will send an official report tomorrow.', 'Người quản lý sẽ gửi một báo cáo chính thức vào ngày mai.', 14, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-15', 'Starter 3', 'starter-3', 'public attention', 'sự chú ý của công chúng', 'Vocab', 'Adjectives', NULL, NULL, 'The new product got a lot of public attention.', 'Sản phẩm mới đã nhận được nhiều sự chú ý của công chúng.', 15, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s3-16', 'Starter 3', 'starter-3', 'a complimentary meal', 'một bữa ăn miễn phí', 'Vocab', 'Adjectives', NULL, NULL, 'Passengers on this flight get a complimentary meal.', 'Hành khách trên chuyến bay này được một bữa ăn miễn phí.', 16, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT INTO word_items (id, set_name, set_slug, en, vi, part, topic, note, other_answers, example_en, example_vi, sort_order, created_at, updated_at) VALUES
('wc-s4-01', 'Starter 4', 'starter-4', 'book a flight', 'đặt một chuyến bay', 'Vocab', 'Verbs 2', NULL, NULL, 'I want to book a flight to Da Nang next week.', 'Tôi muốn đặt một chuyến bay đến Đà Nẵng vào tuần sau.', 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-02', 'Starter 4', 'starter-4', 'reduce investment costs', 'giảm chi phí đầu tư', 'Vocab', 'Verbs 2', NULL, NULL, 'The company wants to reduce investment costs this year.', 'Công ty muốn giảm chi phí đầu tư trong năm nay.', 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-03', 'Starter 4', 'starter-4', 'complain about its service', 'phàn nàn về dịch vụ của nó', 'Vocab', 'Verbs 2', NULL, NULL, 'The customer wrote to complain about its service.', 'Khách hàng đã viết thư để phàn nàn về dịch vụ của nó.', 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-04', 'Starter 4', 'starter-4', 'a decrease in sales', 'sự giảm sút trong doanh số', 'Vocab', 'Verbs 2', NULL, NULL, 'The report shows a decrease in sales this month.', 'Báo cáo cho thấy có sự giảm sút trong doanh số tháng này.', 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-05', 'Starter 4', 'starter-4', 'order a product', 'đặt hàng một sản phẩm', 'Vocab', 'Verbs 2', NULL, NULL, 'You can order a product online at any time.', 'Bạn có thể đặt hàng một sản phẩm trực tuyến vào bất cứ lúc nào.', 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-06', 'Starter 4', 'starter-4', 'launch a new product', 'ra mắt một sản phẩm mới', 'Vocab', 'Verbs 2', NULL, NULL, 'The company will launch a new product next month.', 'Công ty sẽ ra mắt một sản phẩm mới vào tháng sau.', 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-07', 'Starter 4', 'starter-4', 'request a refund', 'yêu cầu hoàn tiền', 'Vocab', 'Verbs 2', NULL, NULL, 'You can request a refund within 30 days.', 'Bạn có thể yêu cầu hoàn tiền trong vòng 30 ngày.', 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-08', 'Starter 4', 'starter-4', 'afford to buy a car', 'có khả năng mua một chiếc xe hơi', 'Vocab', 'Verbs 2', NULL, NULL, 'After saving money, he could afford to buy a car.', 'Sau khi tiết kiệm tiền, anh ấy đã có khả năng mua một chiếc xe hơi.', 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-09', 'Starter 4', 'starter-4', 'renew a visa', 'gia hạn visa', 'Vocab', 'Verbs 2', NULL, NULL, 'I need to renew a visa before my trip.', 'Tôi cần gia hạn visa trước chuyến đi của mình.', 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-10', 'Starter 4', 'starter-4', 'submit the report', 'nộp báo cáo', 'Vocab', 'Verbs 2', NULL, NULL, 'Please submit the report by Friday afternoon.', 'Vui lòng nộp báo cáo trước chiều thứ Sáu.', 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-11', 'Starter 4', 'starter-4', 'reserve a table', 'đặt một chỗ (bàn ăn)', 'Vocab', 'Verbs 2', NULL, NULL, 'We should reserve a table for six people.', 'Chúng ta nên đặt một chỗ (bàn ăn) cho sáu người.', 11, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-12', 'Starter 4', 'starter-4', 'confirm my reservation', 'xác nhận đặt chỗ của tôi', 'Vocab', 'Verbs 2', NULL, NULL, 'I called the hotel to confirm my reservation.', 'Tôi đã gọi cho khách sạn để xác nhận đặt chỗ của tôi.', 12, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-13', 'Starter 4', 'starter-4', 'attract tourists', 'thu hút khách du lịch', 'Vocab', 'Verbs 2', NULL, NULL, 'This beach can attract tourists from around the world.', 'Bãi biển này có thể thu hút khách du lịch từ khắp thế giới.', 13, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-14', 'Starter 4', 'starter-4', 'introduce a new system', 'giới thiệu một hệ thống mới', 'Vocab', 'Verbs 2', NULL, NULL, 'The bank will introduce a new system next year.', 'Ngân hàng sẽ giới thiệu một hệ thống mới vào năm sau.', 14, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-15', 'Starter 4', 'starter-4', 'review the data', 'xem xét lại dữ liệu', 'Vocab', 'Verbs 2', NULL, NULL, 'The manager asked us to review the data again.', 'Người quản lý yêu cầu chúng tôi xem xét lại dữ liệu một lần nữa.', 15, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s4-16', 'Starter 4', 'starter-4', 'postpone the meeting', 'trì hoãn cuộc họp', 'Vocab', 'Verbs 2', NULL, NULL, 'We had to postpone the meeting until next week.', 'Chúng tôi phải trì hoãn cuộc họp đến tuần sau.', 16, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT INTO word_items (id, set_name, set_slug, en, vi, part, topic, note, other_answers, example_en, example_vi, sort_order, created_at, updated_at) VALUES
('wc-s5-01', 'Starter 5', 'starter-5', 'announce a plan', 'công bố một kế hoạch', 'Vocab', 'Verbs 3', NULL, NULL, 'The director will announce a plan on Monday.', 'Giám đốc sẽ công bố một kế hoạch vào thứ Hai.', 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
