('wc-s9-04', 'Starter 9', 'starter-9', 'an informative brochure', 'một tờ rơi mang tính thông tin', 'Vocab', 'Collocations', NULL, NULL, 'The hotel gave us an informative brochure about the city.', 'Khách sạn đã đưa cho chúng tôi một tờ rơi mang tính thông tin về thành phố.', 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-05', 'Starter 9', 'starter-9', 'cordially invite', 'trân trọng kính mời', 'Vocab', 'Collocations', NULL, NULL, 'We cordially invite you to our office opening.', 'Chúng tôi trân trọng kính mời bạn đến buổi khai trương văn phòng.', 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-06', 'Starter 9', 'starter-9', 'in the foreseeable future', 'trong tương lai gần', 'Vocab', 'Collocations', NULL, NULL, 'The company will not move offices in the foreseeable future.', 'Công ty sẽ không dời văn phòng trong tương lai gần.', 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-07', 'Starter 9', 'starter-9', 'attendance records', 'hồ sơ điểm danh', 'Vocab', 'Collocations', NULL, NULL, 'The teacher checks attendance records every week.', 'Giáo viên kiểm tra hồ sơ điểm danh mỗi tuần.', 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-08', 'Starter 9', 'starter-9', 'combined efforts', 'những nỗ lực kết hợp', 'Vocab', 'Collocations', NULL, NULL, 'The project succeeded because of combined efforts.', 'Dự án thành công nhờ những nỗ lực kết hợp.', 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-09', 'Starter 9', 'starter-9', 'hardly ever', 'hiếm khi', 'Vocab', 'Collocations', NULL, NULL, 'He is hardly ever late for work.', 'Anh ấy hiếm khi đi làm muộn.', 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-10', 'Starter 9', 'starter-9', 'power failure', 'sự cố mất điện', 'Vocab', 'Collocations', NULL, NULL, 'A power failure stopped the machines for an hour.', 'Sự cố mất điện đã làm dừng máy trong một giờ.', 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-11', 'Starter 9', 'starter-9', 'defy description', 'khó có thể diễn tả được', 'Vocab', 'Collocations', NULL, NULL, 'The beauty of the view seems to defy description.', 'Vẻ đẹp của khung cảnh dường như khó có thể diễn tả được.', 11, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-12', 'Starter 9', 'starter-9', 'assembly line', 'dây chuyền lắp ráp', 'Vocab', 'Collocations', NULL, NULL, 'Workers stand along the assembly line all day.', 'Công nhân đứng dọc theo dây chuyền lắp ráp cả ngày.', 12, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-13', 'Starter 9', 'starter-9', 'office supplies', 'vật dụng văn phòng', 'Vocab', 'Collocations', NULL, NULL, 'We need to buy more office supplies this week.', 'Chúng ta cần mua thêm vật dụng văn phòng trong tuần này.', 13, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-14', 'Starter 9', 'starter-9', 'safety precautions', 'các biện pháp phòng ngừa an toàn', 'Vocab', 'Collocations', NULL, NULL, 'The factory follows strict safety precautions.', 'Nhà máy tuân theo các biện pháp phòng ngừa an toàn nghiêm ngặt.', 14, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-15', 'Starter 9', 'starter-9', 'protective gear', 'trang bị bảo hộ', 'Vocab', 'Collocations', NULL, NULL, 'Workers must wear protective gear on site.', 'Công nhân phải mặc trang bị bảo hộ tại công trường.', 15, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s9-16', 'Starter 9', 'starter-9', 'customer complaints', 'những phàn nàn của khách hàng', 'Vocab', 'Collocations', NULL, NULL, 'The manager reads customer complaints every morning.', 'Người quản lý đọc những phàn nàn của khách hàng mỗi sáng.', 16, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT INTO word_items (id, set_name, set_slug, en, vi, part, topic, note, other_answers, example_en, example_vi, sort_order, created_at, updated_at) VALUES
('wc-s10-01', 'Starter 10', 'starter-10', 'as a result of', 'do kết quả của', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'The road was closed as a result of the storm.', 'Con đường đã bị đóng do kết quả của cơn bão.', 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-02', 'Starter 10', 'starter-10', 'instead of', 'thay vì', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'She took the bus instead of a taxi.', 'Cô ấy đi xe buýt thay vì xe taxi.', 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-03', 'Starter 10', 'starter-10', 'until further notice', 'cho đến khi có thông báo mới', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'The office will be closed until further notice.', 'Văn phòng sẽ đóng cửa cho đến khi có thông báo mới.', 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-04', 'Starter 10', 'starter-10', 'above my expectations', 'vượt quá mong đợi của tôi', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'The hotel service was above my expectations.', 'Dịch vụ khách sạn đã vượt quá mong đợi của tôi.', 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-05', 'Starter 10', 'starter-10', 'in bulk', 'với số lượng lớn', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'We buy paper in bulk to save money.', 'Chúng tôi mua giấy với số lượng lớn để tiết kiệm tiền.', 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-06', 'Starter 10', 'starter-10', 'in excess of', 'vượt quá', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'The cost was in excess of our budget.', 'Chi phí đã vượt quá ngân sách của chúng tôi.', 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-07', 'Starter 10', 'starter-10', 'with the exception of', 'ngoại trừ', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'Everyone came to the party with the exception of Tom.', 'Mọi người đều đến dự tiệc ngoại trừ Tom.', 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-08', 'Starter 10', 'starter-10', 'in comparison with', 'so với', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'This phone is cheap in comparison with that one.', 'Điện thoại này rẻ so với cái kia.', 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-09', 'Starter 10', 'starter-10', 'out of print', 'hết hàng, không còn được in', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'That book is now out of print.', 'Cuốn sách đó hiện đã hết hàng, không còn được in.', 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-10', 'Starter 10', 'starter-10', 'in charge of', 'chịu trách nhiệm về', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'She is in charge of the marketing team.', 'Cô ấy chịu trách nhiệm về nhóm marketing.', 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-11', 'Starter 10', 'starter-10', 'at the latest', 'trễ nhất là', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'Please send the report by Friday at the latest.', 'Vui lòng gửi báo cáo trước thứ Sáu, trễ nhất là vậy.', 11, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-12', 'Starter 10', 'starter-10', 'in detail', 'một cách chi tiết', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'He explained the plan in detail.', 'Anh ấy đã giải thích kế hoạch một cách chi tiết.', 12, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-13', 'Starter 10', 'starter-10', 'in writing', 'bằng văn bản', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'Please confirm your order in writing.', 'Vui lòng xác nhận đơn đặt hàng của bạn bằng văn bản.', 13, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-14', 'Starter 10', 'starter-10', 'on request', 'khi có yêu cầu', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'A menu in English is available on request.', 'Menu bằng tiếng Anh có sẵn khi có yêu cầu.', 14, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-15', 'Starter 10', 'starter-10', 'on schedule', 'đúng theo lịch trình', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'The project is still on schedule.', 'Dự án vẫn đang đúng theo lịch trình.', 15, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s10-16', 'Starter 10', 'starter-10', 'in duplicate', 'thành hai bản', 'Vocab', 'Prep. Phrases 1', NULL, NULL, 'Please print the form in duplicate.', 'Vui lòng in mẫu đơn thành hai bản.', 16, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT INTO word_items (id, set_name, set_slug, en, vi, part, topic, note, other_answers, example_en, example_vi, sort_order, created_at, updated_at) VALUES
('wc-s11-01', 'Starter 11', 'starter-11', 'in a timely manner', 'một cách kịp thời', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'Please reply to emails in a timely manner.', 'Vui lòng trả lời email một cách kịp thời.', 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-02', 'Starter 11', 'starter-11', 'under warranty', 'còn trong thời hạn bảo hành', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'This laptop is still under warranty.', 'Chiếc laptop này vẫn còn trong thời hạn bảo hành.', 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-03', 'Starter 11', 'starter-11', 'in an effort to', 'trong một nỗ lực để', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'The company cut prices in an effort to attract customers.', 'Công ty đã giảm giá trong một nỗ lực để thu hút khách hàng.', 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-04', 'Starter 11', 'starter-11', 'in advance', 'trước', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'Please book your ticket in advance.', 'Vui lòng đặt vé trước.', 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-05', 'Starter 11', 'starter-11', 'on behalf of', 'đại diện cho', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'He signed the document on behalf of the company.', 'Anh ấy đã ký giấy tờ đại diện cho công ty.', 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-06', 'Starter 11', 'starter-11', 'for your convenience', 'để bạn thuận tiện hơn', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'We added a map for your convenience.', 'Chúng tôi đã thêm bản đồ để bạn thuận tiện hơn.', 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-07', 'Starter 11', 'starter-11', 'in terms of', 'về mặt', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'The two plans are similar in terms of price.', 'Hai kế hoạch tương tự nhau về mặt giá cả.', 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-08', 'Starter 11', 'starter-11', 'at all times', 'mọi lúc', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'Staff must wear ID cards at all times.', 'Nhân viên phải mang thẻ tên vào mọi lúc.', 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-09', 'Starter 11', 'starter-11', 'in stock', 'còn hàng trong kho', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'This model is currently in stock.', 'Mẫu này hiện đang còn hàng trong kho.', 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-10', 'Starter 11', 'starter-11', 'at one''s expense', 'bằng chi phí của ai đó', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'He had to travel at one''s expense last year.', 'Anh ấy phải đi công tác bằng chi phí của ai đó vào năm ngoái.', 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-11', 'Starter 11', 'starter-11', 'with caution', 'một cách cẩn trọng', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'Drivers should proceed with caution near schools.', 'Người lái xe nên di chuyển một cách cẩn trọng gần trường học.', 11, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-12', 'Starter 11', 'starter-11', 'on duty', 'đang trong ca làm việc', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'Two guards are on duty every night.', 'Hai bảo vệ đang trong ca làm việc mỗi đêm.', 12, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-13', 'Starter 11', 'starter-11', 'in particular', 'đặc biệt, nói riêng', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'I enjoyed the food, this dish in particular.', 'Tôi thích món ăn, món này đặc biệt, nói riêng.', 13, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-14', 'Starter 11', 'starter-11', 'in cooperation with', 'hợp tác với', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'The school built the library in cooperation with a company.', 'Nhà trường đã xây thư viện hợp tác với một công ty.', 14, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-15', 'Starter 11', 'starter-11', 'on the agenda', 'trong chương trình nghị sự', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'The budget is on the agenda for today''s meeting.', 'Ngân sách nằm trong chương trình nghị sự cho cuộc họp hôm nay.', 15, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s11-16', 'Starter 11', 'starter-11', 'in honor of', 'để tôn vinh', 'Vocab', 'Prep. Phrases 2', NULL, NULL, 'The event was held in honor of the retiring manager.', 'Sự kiện được tổ chức để tôn vinh người quản lý sắp nghỉ hưu.', 16, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT INTO word_items (id, set_name, set_slug, en, vi, part, topic, note, other_answers, example_en, example_vi, sort_order, created_at, updated_at) VALUES
('wc-s12-01', 'Starter 12', 'starter-12', 'a preference for', 'sự ưu tiên đối với', 'Vocab', 'Noun + Preposition', NULL, NULL, 'She has a preference for window seats.', 'Cô ấy có sự ưu tiên đối với ghế cạnh cửa sổ.', 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-02', 'Starter 12', 'starter-12', 'a subscription to', 'một sự đăng ký cho', 'Vocab', 'Noun + Preposition', NULL, NULL, 'He bought a subscription to a business magazine.', 'Anh ấy đã mua một sự đăng ký cho một tạp chí kinh doanh.', 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-03', 'Starter 12', 'starter-12', 'a variety of', 'nhiều loại', 'Vocab', 'Noun + Preposition', NULL, NULL, 'The store sells a variety of fruits.', 'Cửa hàng bán nhiều loại trái cây.', 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-04', 'Starter 12', 'starter-12', 'a major impact on', 'một tác động lớn đến', 'Vocab', 'Noun + Preposition', NULL, NULL, 'The new law had a major impact on small businesses.', 'Luật mới đã có một tác động lớn đến các doanh nghiệp nhỏ.', 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-05', 'Starter 12', 'starter-12', 'a demand for', 'nhu cầu về', 'Vocab', 'Noun + Preposition', NULL, NULL, 'There is a demand for skilled workers this year.', 'Có nhu cầu về công nhân có kỹ năng trong năm nay.', 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-06', 'Starter 12', 'starter-12', 'a tax on', 'một loại thuế đánh vào', 'Vocab', 'Noun + Preposition', NULL, NULL, 'The government put a tax on imported cars.', 'Chính phủ đã áp một loại thuế đánh vào xe hơi nhập khẩu.', 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-07', 'Starter 12', 'starter-12', 'the majority of', 'phần lớn', 'Vocab', 'Noun + Preposition', NULL, NULL, 'The majority of workers agreed with the plan.', 'Phần lớn công nhân đã đồng ý với kế hoạch.', 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-08', 'Starter 12', 'starter-12', 'exposure to', 'sự tiếp xúc với', 'Vocab', 'Noun + Preposition', NULL, NULL, 'Long exposure to the sun can be harmful.', 'Sự tiếp xúc với nắng lâu có thể gây hại.', 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-09', 'Starter 12', 'starter-12', 'stance on', 'quan điểm về', 'Vocab', 'Noun + Preposition', NULL, NULL, 'The manager explained his stance on the new rule.', 'Người quản lý đã giải thích quan điểm về quy định mới.', 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-10', 'Starter 12', 'starter-12', 'guarantee of', 'sự bảo đảm về', 'Vocab', 'Noun + Preposition', NULL, NULL, 'The shop offers a guarantee of quality.', 'Cửa hàng cung cấp một sự bảo đảm về chất lượng.', 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-11', 'Starter 12', 'starter-12', 'commitment to', 'sự cam kết đối với', 'Vocab', 'Noun + Preposition', NULL, NULL, 'The team showed a commitment to the project.', 'Nhóm đã thể hiện sự cam kết đối với dự án.', 11, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-12', 'Starter 12', 'starter-12', 'development in', 'sự phát triển trong', 'Vocab', 'Noun + Preposition', NULL, NULL, 'There has been development in this area.', 'Đã có sự phát triển trong khu vực này.', 12, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-13', 'Starter 12', 'starter-12', 'respect for', 'sự tôn trọng đối với', 'Vocab', 'Noun + Preposition', NULL, NULL, 'He has respect for his teacher.', 'Anh ấy có sự tôn trọng đối với giáo viên của mình.', 13, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-14', 'Starter 12', 'starter-12', 'access to', 'quyền truy cập đến', 'Vocab', 'Noun + Preposition', NULL, NULL, 'Employees have access to the online system.', 'Nhân viên có quyền truy cập đến hệ thống trực tuyến.', 14, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-15', 'Starter 12', 'starter-12', 'a decline in', 'sự suy giảm trong', 'Vocab', 'Noun + Preposition', NULL, NULL, 'The company saw a decline in profit last year.', 'Công ty đã thấy sự suy giảm trong lợi nhuận vào năm ngoái.', 15, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s12-16', 'Starter 12', 'starter-12', 'an opinion about', 'một ý kiến về', 'Vocab', 'Noun + Preposition', NULL, NULL, 'She shared an opinion about the new policy.', 'Cô ấy đã chia sẻ một ý kiến về chính sách mới.', 16, UTC_TIMESTAMP(), UTC_TIMESTAMP());
INSERT INTO word_items (id, set_name, set_slug, en, vi, part, topic, note, other_answers, example_en, example_vi, sort_order, created_at, updated_at) VALUES
('wc-s13-01', 'Starter 13', 'starter-13', 'be willing to do', 'sẵn lòng làm', 'Vocab', 'Expr. of Adjectives', NULL, NULL, 'You must be willing to do extra work this week.', 'Bạn phải sẵn lòng làm thêm việc trong tuần này.', 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s13-02', 'Starter 13', 'starter-13', 'be involved in', 'tham gia vào', 'Vocab', 'Expr. of Adjectives', NULL, NULL, 'He needs to be involved in this new project.', 'Anh ấy cần tham gia vào dự án mới này.', 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s13-03', 'Starter 13', 'starter-13', 'be capable of', 'có khả năng', 'Vocab', 'Expr. of Adjectives', NULL, NULL, 'This machine needs to be capable of printing very fast.', 'Máy này cần có khả năng in rất nhanh.', 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s13-04', 'Starter 13', 'starter-13', 'be vulnerable to', 'dễ bị ảnh hưởng bởi', 'Vocab', 'Expr. of Adjectives', NULL, NULL, 'Small shops can be vulnerable to price changes.', 'Các cửa hàng nhỏ có thể dễ bị ảnh hưởng bởi sự thay đổi giá.', 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s13-05', 'Starter 13', 'starter-13', 'be likely to', 'có khả năng sẽ', 'Vocab', 'Expr. of Adjectives', NULL, NULL, 'It seems to be likely to happen soon.', 'Điều đó có khả năng sẽ xảy ra sớm.', 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s13-06', 'Starter 13', 'starter-13', 'be payable to', 'phải trả cho', 'Vocab', 'Expr. of Adjectives', NULL, NULL, 'The check needs to be payable to the company.', 'Tấm séc cần phải trả cho công ty.', 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s13-07', 'Starter 13', 'starter-13', 'be attentive to', 'chú ý đến', 'Vocab', 'Expr. of Adjectives', NULL, NULL, 'A good waiter must be attentive to customers.', 'Một người phục vụ tốt phải chú ý đến khách hàng.', 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wc-s13-08', 'Starter 13', 'starter-13', 'be beneficial to', 'có lợi cho', 'Vocab', 'Expr. of Adjectives', NULL, NULL, 'Regular exercise can be beneficial to your health.', 'Tập thể dục thường xuyên có thể có lợi cho sức khỏe của bạn.', 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
