-- Replace the old placeholder "Starter 1" / "Sprinter 1" seed with a real 13-set
-- Starter curriculum (collocations, nouns, adjectives, verb phrases, prepositional
-- phrases...), supplied by the site owner as JSON exports of the "Master" sheet.

DELETE FROM word_items WHERE set_slug IN (
  'starter-1', 'starter-2', 'starter-3', 'starter-4', 'starter-5', 'starter-6', 'starter-7',
  'starter-8', 'starter-9', 'starter-10', 'starter-11', 'starter-12', 'starter-13', 'sprinter-1'
);













